"""Implementation of Taplo's toml-test decoder output format."""
import datetime
import json
import tomllib
from typing import Any


def _encode(value: Any) -> Any:
    if isinstance(value, dict):
        return {key: _encode(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_encode(item) for item in value]
    if isinstance(value, bool):
        return {"type": "bool", "value": "true" if value else "false"}
    if isinstance(value, int):
        return {"type": "integer", "value": str(value)}
    if isinstance(value, float):
        # Rust's float display keeps integral floats distinguishable.
        rendered = repr(value)
        if "e" not in rendered.lower() and "." not in rendered:
            rendered += ".0"
        return {"type": "float", "value": rendered}
    if isinstance(value, str):
        return {"type": "string", "value": value}
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return {"type": "datetime", "value": json.dumps(value.isoformat(), ensure_ascii=False)}
    return value


def decode(source: str) -> str:
    """Parse TOML and return its compact toml-test JSON representation."""
    parsed = tomllib.loads(source)
    return json.dumps(_encode(parsed), ensure_ascii=False, separators=(",", ":"))

