"""Small, dependency-free implementation of Taplo's common formatting behavior."""
import re

def format_text(src, options=None):
    opts = {"compact_entries": False, "compact_arrays": True, "array_trailing_comma": True,
            "trailing_newline": True, "crlf": False, "allowed_blank_lines": 2}
    opts.update(options or {})
    # Normalize line endings, then format each statement while retaining comments and table order.
    lines = src.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    if opts.get("array_auto_collapse", True):
        lines = _collapse_multiline_arrays(lines)
    out=[]
    blank=0
    array_depth=0
    for line in lines:
        s=line.strip()
        if not s:
            blank += 1
            if blank <= int(opts.get("allowed_blank_lines", 2)) and out and out[-1] != "": out.append("")
            continue
        blank=0
        continuation = array_depth > 0
        if s.startswith("#") or (s.startswith("[") and s.endswith("]")):
            out.append(s); continue
        # Locate assignment = outside quoted strings and nested values.
        quote=None; esc=False; depth=0; eq=-1
        for i,c in enumerate(s):
            if quote:
                if esc: esc=False
                elif c=='\\' and quote=='"': esc=True
                elif c==quote: quote=None
            elif c in ('"', "'"): quote=c
            elif c in "[{(": depth+=1
            elif c in "]})": depth-=1
            elif c=="=" and depth==0: eq=i; break
        if eq >= 0:
            key=s[:eq].strip(); val=s[eq+1:].strip()
            # Normalize whitespace around separators inside arrays/inline tables without changing strings.
            val=_normalize(val, bool(opts.get("compact_arrays", True)), bool(opts.get("compact_inline_tables", False)), bool(opts.get("compact_entries", False)))
            sep="=" if opts.get("compact_entries") else " = "
            s=key + sep + val
            width=int(opts.get("column_width", 80))
            if (opts.get("array_auto_expand", True) and len(s)>width and
                    val.startswith("[") and val.endswith("]")):
                items=_array_items(val[1:-1])
                if items:
                    comma=bool(opts.get("array_trailing_comma", True))
                    s=key + sep + "[\n" + "\n".join(
                        "  " + item + ("," if comma else "") for item in items
                    ) + "\n]"
            if opts.get("indent_entries") and any(x.startswith("[") for x in out):
                s=str(opts.get("indent_string", "  "))+s
        if continuation and not s.startswith("]"):
            s = str(opts.get("indent_string", "  ")) + s
        out.append(s)
        array_depth += _array_depth(line)
    if opts.get("reorder_keys"):
        start=0
        while start < len(out):
            if not out[start] or out[start].startswith("#") or out[start].startswith("["):
                start += 1; continue
            end=start
            while end<len(out) and out[end] and not out[end].startswith("#") and not out[end].startswith("["): end+=1
            out[start:end]=sorted(out[start:end], key=lambda x:x.split("=",1)[0].strip())
            start=end
    while out and out[-1]=="": out.pop()
    result="\n".join(out)
    if opts.get("trailing_newline", True) and result: result += "\n"
    if opts.get("crlf"): result=result.replace("\n","\r\n")
    return result

def _array_items(body):
    """Split an array body at commas outside nested values and quoted strings."""
    items=[]; start=0; stack=[]; quote=None; esc=False
    pairs={"]":"[", "}":"{", ")":"("}
    for i,ch in enumerate(body):
        if quote:
            if esc: esc=False
            elif ch=="\\" and quote=='"': esc=True
            elif ch==quote: quote=None
        elif ch in ('"', "'"): quote=ch
        elif ch in "[{(": stack.append(ch)
        elif ch in "]})":
            if stack and stack[-1]==pairs[ch]: stack.pop()
        elif ch=="," and not stack:
            item=body[start:i].strip()
            if item: items.append(item)
            start=i+1
    tail=body[start:].strip()
    if tail: items.append(tail)
    return items

def _array_depth(text):
    quote = None
    escaped = False
    depth = 0
    for char in text:
        if quote:
            if escaped:
                escaped = False
            elif char == "\\" and quote == '"':
                escaped = True
            elif char == quote:
                quote = None
        elif char in ('"', "'"):
            quote = char
        elif char == "#":
            break
        elif char == "[":
            depth += 1
        elif char == "]":
            depth -= 1
    return depth

def _collapse_multiline_arrays(lines):
    result = []
    i = 0
    while i < len(lines):
        line = lines[i]
        if _array_depth(line) > 0:
            parts = [line.strip()]
            depth = _array_depth(line)
            i += 1
            while i < len(lines) and depth > 0:
                part = lines[i].strip()
                parts.append(part)
                depth += _array_depth(part)
                i += 1
            merged = " ".join(part for part in parts if part)
            merged = re.sub(r",\s*\]", "]", merged)
            result.append(merged)
        else:
            result.append(line)
            i += 1
    return result

