    # Normalize separators while retaining quoted strings verbatim.
    res=[]; quote=None; esc=False; stack=[]; pending=False
    for i,c in enumerate(s):
        if quote:
            res.append(c)
            if esc: esc=False
            elif c=='\\' and quote=='"': esc=True
            elif c==quote: quote=None
            continue
        if c in ('"',"'"):
            if pending and res and not res[-1].isspace() and res[-1] not in "[{": res.append(" ")
            pending=False; quote=c; res.append(c); continue
        if c.isspace(): pending=True; continue
        if c=='[':
            if pending and res and not res[-1].isspace() and res[-1] != "[": res.append(" ")
            pending=False; stack.append('['); res.append("[" if compact_arrays else "[ "); continue
        if c=='{':
            if pending and res and not res[-1].isspace() and res[-1] not in "[{": res.append(" ")
