            if not compact_inline_tables and res and res[-1]!='{': res.append(" ")
            res.append("}"); pending=False
            if stack: stack.pop()
            continue
        if c==',':
            while res and res[-1]==' ': res.pop()
            res.extend(", "); pending=False; continue
        if c=='=':
