            while res and res[-1]==' ': res.pop()
            res.extend(" #" + s[i+1:])
            break
        if pending and res and not res[-1].isspace() and res[-1] not in "[{": res.append(" ")
        pending=False; res.append(c)

    return ''.join(res).strip()

