def _decoder_error(source: str, valid_value) -> str | None:
    pending = ""
    offset = 0
    statement_start = 0
    for raw in source.splitlines(keepends=True):
        content = raw.rstrip("\r\n")
        multiline_open = pending.count('"""') % 2 or pending.count("'''") % 2
        line = content.strip() if multiline_open else _strip_comment(content).strip()
        if not line or line.startswith("#"):
            offset += len(raw)
            continue
        if not pending:
            statement_start = offset + len(content) - len(content.lstrip())
        pending = (pending + "\n" + line).strip() if pending else line
        offset += len(raw)
        if _unclosed(pending):
            continue
        statement, pending = pending, ""
        if statement.startswith("[") and statement.endswith("]"):
            continue
        eq = _find_eq(statement)
        if eq < 0:
            end = statement_start + len(statement)
            if end < len(source):
                return f'expected "=" ({end}..{end + 1})'
            return f"unexpected EOF ({end}..{end})"
        value = _strip_comment(statement[eq + 1:]).strip()
        value_start = statement_start + eq + 1
        while value_start < len(source) and source[value_start].isspace() and source[value_start] not in "\r\n":
            value_start += 1
        if not value:
            if value_start < len(source):
                return f"expected value ({value_start}..{value_start + 1})"
            return f"expected value ({value_start}..{value_start})"
        if not valid_value(value):
            return f"expected value ({value_start}..{value_start + len(value)})"
    if pending:
        end = len(source)
        return f"unexpected EOF ({end}..{end})"
    return None


