def _schema_error(value, schema, path="document"):
    """Validate common Draft 4 constraints without external dependencies."""
    if not isinstance(schema, dict):
        return None
    kinds = {
        "object": lambda x: isinstance(x, dict),
        "array": lambda x: isinstance(x, list),
        "string": lambda x: isinstance(x, str),
        "integer": lambda x: isinstance(x, int) and not isinstance(x, bool),
        "number": lambda x: isinstance(x, (int, float)) and not isinstance(x, bool),
        "boolean": lambda x: isinstance(x, bool),
        "null": lambda x: x is None,
    }
    expected = schema.get("type")
    accepted = expected if isinstance(expected, list) else [expected]
    if any(kind in kinds for kind in accepted) and not any(kinds[kind](value) for kind in accepted if kind in kinds):
        return f"{json.dumps(value, ensure_ascii=False)} is not of type {json.dumps(expected)}"
    if "allOf" in schema:
        for option in schema["allOf"]:
            error = _schema_error(value, option, path)
            if error: return error
    if "anyOf" in schema and not any(_schema_error(value, option, path) is None for option in schema["anyOf"]):
        return f"{json.dumps(value, ensure_ascii=False)} is not valid under any of the given schemas"
    if "oneOf" in schema:
        matches = sum(_schema_error(value, option, path) is None for option in schema["oneOf"])
        if matches != 1: return f"{json.dumps(value, ensure_ascii=False)} is not valid under exactly one of the given schemas"
    if "not" in schema and _schema_error(value, schema["not"], path) is None:
        return f"{json.dumps(value, ensure_ascii=False)} is valid under a schema that should not match"
    if "enum" in schema and value not in schema["enum"]:
        return f"{value!r} is not one of {schema['enum']!r}"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and (value < schema["minimum"] or (schema.get("exclusiveMinimum") is True and value == schema["minimum"])):
            return f"{value} is less than the minimum of {schema['minimum']}"
        if "maximum" in schema and (value > schema["maximum"] or (schema.get("exclusiveMaximum") is True and value == schema["maximum"])):
            return f"{value} is greater than the maximum of {schema['maximum']}"
        if isinstance(schema.get("exclusiveMinimum"), (int, float)) and not isinstance(schema["exclusiveMinimum"], bool) and value <= schema["exclusiveMinimum"]:
            return f"{value} is less than or equal to the minimum of {schema['exclusiveMinimum']}"
        if isinstance(schema.get("exclusiveMaximum"), (int, float)) and not isinstance(schema["exclusiveMaximum"], bool) and value >= schema["exclusiveMaximum"]:
            return f"{value} is greater than or equal to the maximum of {schema['exclusiveMaximum']}"
    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            return f"{value!r} is too short"
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            return f"{value!r} is too long"
        if "pattern" in schema and not re.search(schema["pattern"], value):
            return f"{value!r} does not match {schema['pattern']!r}"
    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value:
                return f"{key!r} is a required property"
        properties = schema.get("properties", {})
        for key, child in value.items():
            if key in properties:
                error = _schema_error(child, properties[key], str(key))
                if error:
                    return error
            elif schema.get("additionalProperties") is False:
                return f"Additional properties are not allowed ({key!r} was unexpected)"
    if isinstance(value, list) and isinstance(schema.get("items"), dict):
        for index, child in enumerate(value):
            error = _schema_error(child, schema["items"], f"{path}[{index}]")
            if error:
                return error
    if isinstance(value, list) and schema.get("uniqueItems"):
        encoded = [json.dumps(item, sort_keys=True, default=str) for item in value]
        if len(encoded) != len(set(encoded)):
            return "array items are not unique"
    return None


